class LRUCache:
    """
    LRUCache is a data structure that manages a limited-size cache with a 
    least-recently-used eviction policy. It employs a hashmap along with a 
    fixed-size circular buffer to enable O(1) get and put operations while 
    tracking usage order efficiently.
    """

    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.keys = []
        self.current_size = 0

    def get(self, key: int) -> int:
        if key in self.cache:
            self.keys.remove(key)
            self.keys.insert(0, key)
            return self.cache[key]
        return -1

    def put(self, key: int, value: int) -> None:
        if key in self.cache:
            self.cache[key] = value
            self.keys.remove(key)
            self.keys.insert(0, key)
        else:
            if self.current_size >= self.capacity:
                oldest_key = self.keys.pop()
                del self.cache[oldest_key]
            self.cache[key] = value
            self.keys.insert(0, key)
            self.current_size += 1

class LRUCache:
    """
    LRUCache is a data structure that manages a limited-size cache with a 
    least-recently-used eviction policy. It employs a hashmap for O(1) key access 
    and a regular list to maintain the insertion order of keys, allowing efficient 
    tracking of the least recently used items.
    """

    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.order = []

    def get(self, key: int) -> int:
        if key in self.cache:
            self.order.remove(key)
            self.order.append(key)
            return self.cache[key]
        return -1

    def put(self, key: int, value: int) -> None:
        if key in self.cache:
            self.cache[key] = value
            self.order.remove(key)
            self.order.append(key)
        else:
            if len(self.cache) >= self.capacity:
                lru_key = self.order.pop(0)
                del self.cache[lru_key]
            self.cache[key] = value
            self.order.append(key)
